begin;
do $$
declare au uuid:=gen_random_uuid(); outsider_auth uuid:=gen_random_uuid(); admin_auth uuid:=gen_random_uuid();
 u uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); admin_user uuid:=gen_random_uuid();
 a uuid; salon uuid; claim uuid; report uuid; c uuid; c2 uuid; content uuid:=gen_random_uuid(); a2 uuid; salon2 uuid; competitor uuid; phone_claim uuid; stamp timestamptz;
 j jsonb; n integer; denied boolean; limited_role uuid; request_key uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email,raw_app_meta_data) values(au,'review-qa-'||au||'@example.invalid','{"provider":"qa_fixture"}'),(outsider_auth,'review-qa-'||outsider_auth||'@example.invalid','{"provider":"qa_fixture"}'),(admin_auth,'review-qa-'||admin_auth||'@example.invalid','{"provider":"qa_fixture"}');
 insert into users(id,auth_user_id,email,status) values(u,au,'review-qa-'||au||'@example.invalid','active'),(outsider,outsider_auth,'review-qa-'||outsider_auth||'@example.invalid','active'),(admin_user,admin_auth,'review-qa-'||admin_auth||'@example.invalid','active');
 insert into platform_admin_memberships(user_id,role_id,status) select admin_user,id,'active' from platform_admin_roles where slug='platform_owner';
 insert into accounts(name,status) values('Review communication QA','active') returning id into a;
 insert into locations(account_id,name,status,phone) values(a,'Review communication QA salon','active','555-234-6789') returning id into salon;
 insert into salon_settings(salon_id,business_name,public_discovery_enabled) values(salon,'Review QA',true) on conflict(salon_id) do update set public_discovery_enabled=true;
 insert into salon_directory_listings(listing_id,salon_id,source_url,source_type,collected_on) values('review-qa-'||salon,salon,'https://example.invalid','directory',current_date);
 insert into notification_preferences(user_id,category,enabled) values(u,'team',false),(u,'comments',false);
 perform set_config('request.jwt.claim.sub',au::text,true);
 claim:=request_business_claim_support(salon,'I own this salon and need manual ownership verification.');
 report:=get_review_support_link('claim',claim);
 if report is null then raise exception 'Claim conversation missing'; end if;
 if get_business_claim_requests(salon)->0->>'support_report_id' is distinct from report::text then raise exception 'Claim page/admin response lacks conversation link'; end if;
 if (select count(*) from app_notifications where recipient_user_id=u and href='/support/'||report)<>1 then raise exception 'Receipt missing or duplicated, or disabled by preference'; end if;
 denied:=false;begin perform add_support_case_attachment(report,report::text||'/../escape.png','Invalid traversal proof');exception when others then denied:=true;end;
 if not denied then raise exception 'Evidence path traversal accepted';end if;
 perform set_config('request.jwt.claim.sub',outsider_auth::text,true);
 denied:=false;begin perform get_review_support_link('claim',claim);exception when others then denied:=true;end;
 if not denied then raise exception 'Outsider read claim link'; end if;
 denied:=false;begin perform get_support_conversation(report);exception when others then denied:=true;end;
 if not denied then raise exception 'Outsider read conversation'; end if;
 denied:=false;begin perform send_support_case_message(report,'Unauthorized reply');exception when others then denied:=true;end;
 if not denied then raise exception 'Outsider replied'; end if;
 denied:=false;begin perform review_business_claim_with_message(claim,'approved','Forged approval');exception when others then denied:=true;end;
 if not denied then raise exception 'Nonadmin approved claim'; end if;
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 perform review_business_claim_with_message(claim,'needs_info','Please upload your business license and authorization.','INTERNAL-SECRET-REVIEW-QA');
 if (select status from business_claim_requests where id=claim)<>'needs_info' then raise exception 'Needs-info state missing'; end if;
 if (select status from platform_reports where id=report)<>'action_required' then raise exception 'Conversation not waiting for user'; end if;
 select count(*) into n from app_notifications where recipient_user_id=u and href='/support/'||report;
 if n<>2 then raise exception 'Decision notification missing/duplicated'; end if;
 denied:=false;begin perform review_business_claim_with_message(claim,'needs_info','Please upload again');exception when others then denied:=true;end;
 if not denied then raise exception 'Duplicate information request accepted'; end if;
 perform set_config('request.jwt.claim.sub',au::text,true);
 j:=get_support_conversation(report);
 if j::text like '%INTERNAL-SECRET%' or get_business_claim_requests(salon)::text like '%INTERNAL-SECRET%' then raise exception 'Internal claim note leaked'; end if;
 if j::text not like '%business license%' then raise exception 'Requested documents not visible'; end if;
 denied:=false;begin perform begin_business_claim(salon,u,'sms');exception when others then denied:=true;end;
 if not denied then raise exception 'Needs-info restarted phone verification'; end if;
 perform send_support_case_message_once(report,'I have provided the requested ownership details.',request_key);
 select count(*) into n from support_case_messages where report_id=report;
 perform send_support_case_message_once(report,'I have provided the requested ownership details.',request_key);
 if n<>(select count(*) from support_case_messages where report_id=report) then raise exception 'Network retry duplicated reply'; end if;
 if (select count(*) from platform_admin_activity_events where report_id=report and kind='user_reply')<>1 then raise exception 'Team reply notification missing or duplicated on retry'; end if;
 denied:=false;begin perform send_support_case_message_once(report,'Changed message',request_key);exception when others then denied:=true;end;
 if not denied then raise exception 'Message request key was reused for changed content'; end if;
 if (select status from business_claim_requests where id=claim)<>'waiting' then raise exception 'User reply did not requeue claim'; end if;
 if exists(select 1 from salon_memberships where salon_id=salon and user_id=u and status='active') then raise exception 'Reply granted ownership'; end if;
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 perform send_support_case_message(report,'Thank you. Your evidence is under review.');
 if (select status from platform_reports where id=report)<>'under_review' then raise exception 'Ordinary support reply incorrectly waits for user information';end if;
 perform review_business_claim_with_message(claim,'rejected','The document does not establish your authority. Provide an authorization letter.','PRIVATE-REJECTION-QA');
 perform set_config('request.jwt.claim.sub',au::text,true);
 denied:=false;begin perform send_support_case_message(report,'Please reconsider this claim');exception when others then denied:=true;end;
 if not denied then raise exception 'Closed conversation reopened without explicit request'; end if;
 perform send_support_case_message(report,'Here is additional evidence for reconsideration.',true);
 if (select status from business_claim_requests where id=claim)<>'waiting' then raise exception 'Rejected claim did not requeue'; end if;
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 perform review_business_claim_with_message(claim,'approved','Ownership evidence has been verified.');
 if not exists(select 1 from salon_memberships where salon_id=salon and user_id=u and status='active') then raise exception 'Approved claim did not grant membership'; end if;
 select count(*) into n from app_notifications where recipient_user_id=u and href='/support/'||report;
 denied:=false;begin perform review_business_claim_with_message(claim,'approved','Repeated approval');exception when others then denied:=true;end;
 if not denied or n<>(select count(*) from app_notifications where recipient_user_id=u and href='/support/'||report) then raise exception 'Replay sent a duplicate decision'; end if;
 perform set_config('request.jwt.claim.sub',au::text,true);
 perform send_support_case_message(report,'I have another access question.',true);
 if (select status from business_claim_requests where id=claim)<>'approved' then raise exception 'Support reopen changed approved ownership'; end if;
 -- A fake content ID is isolated: no real content is touched by these review calls.
 insert into post_safety_cases(source_type,source_id,origin,reason,content_snapshot,reporter_user_id)
 values('beauty_post',content,'user','unwanted','{}',u) returning id into c;
 report:=get_review_support_link('post_report',c);
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 request_key:=gen_random_uuid();
 perform review_post_safety_with_message(c,'request_info','INTERNAL-CONTENT-QA','Please provide the date and a screenshot of the issue.',request_key);
 select count(*) into n from app_notifications where recipient_user_id=u and href='/support/'||report;
 perform review_post_safety_with_message(c,'request_info','INTERNAL-CONTENT-QA','Please provide the date and a screenshot of the issue.',request_key);
 if n<>(select count(*) from app_notifications where recipient_user_id=u and href='/support/'||report) then raise exception 'Review retry duplicated information request'; end if;
 if (select status from post_safety_cases where id=c)<>'pending' or (select status from platform_reports where id=report)<>'action_required' then raise exception 'Information request finalized moderation'; end if;
 perform set_config('request.jwt.claim.sub',au::text,true);
 perform send_support_case_message(report,'The issue occurred yesterday.');
 j:=get_support_conversation(report);
 if j::text like '%INTERNAL-CONTENT-QA%' then raise exception 'Internal moderation note leaked'; end if;
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 perform review_post_safety_with_message(c,'keep_public','INTERNAL-DISMISS-QA','We did not find a policy violation in the reported content.');
 perform set_config('request.jwt.claim.sub',au::text,true);
 j:=get_support_conversation(report);
 if j::text like '%INTERNAL-DISMISS-QA%' or j::text not like '%policy violation%' then raise exception 'Public/internal explanations not separated'; end if;
 perform send_support_case_message(report,'Please reconsider with this additional evidence.',true);
 if (select status from post_safety_cases where id=c)<>'dismissed' then raise exception 'User reply reversed moderation'; end if;
 denied:=false;begin perform reopen_content_report_review(c);exception when others then denied:=true;end;
 if not denied then raise exception 'User reopened moderation review'; end if;
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 perform reopen_content_report_review(c);
 if (select status from post_safety_cases where id=c)<>'pending' then raise exception 'Admin could not reopen appealed content report'; end if;
 -- Multiple reporters receive their own safe result, without leaking the reviewed reporter's text.
 insert into post_safety_cases(source_type,source_id,origin,reason,content_snapshot,reporter_user_id)
 values('beauty_post',gen_random_uuid(),'user','scam','{}',u) returning id,source_id into c,content;
 insert into post_safety_cases(source_type,source_id,origin,reason,content_snapshot,reporter_user_id)
 values('beauty_post',content,'user','scam','{}',outsider) returning id into c2;
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 perform review_post_safety_with_message(c,'delete','INTERNAL-DELETE-QA','The reported offer violated our policy.');
 report:=get_review_support_link('post_report',c2);
 perform set_config('request.jwt.claim.sub',outsider_auth::text,true);
 j:=get_support_conversation(report);
 if j::text like '%INTERNAL-DELETE-QA%' or j::text like '%reported offer%' or j::text not like '%took action%' then raise exception 'Bulk decision disclosed another report or missed result'; end if;
 if not exists(select 1 from app_notifications where recipient_user_id=outsider and href='/support/'||report and notification_type='review_decision') then raise exception 'Other reporter missed notification'; end if;
 if has_table_privilege('authenticated','review_support_links','select') or has_function_privilege('authenticated','ensure_review_support_case(text,uuid)','execute') or has_function_privilege('anon','get_review_support_link(text,uuid)','execute') then raise exception 'Private linkage exposed'; end if;
 -- A competing needs-info claim blocks otherwise eligible automatic phone approval.
 insert into accounts(name,status) values('Competing evidence QA','active') returning id into a2;
 insert into locations(account_id,name,status,phone) values(a2,'Competing evidence QA salon','active','555-234-6791') returning id into salon2;
 insert into salon_settings(salon_id,business_name,public_discovery_enabled) values(salon2,'Competing evidence QA',true);
 insert into salon_directory_listings(listing_id,salon_id,source_url,source_type,collected_on) values('review-competing-qa-'||salon2,salon2,'https://example.invalid','business_website',current_date);
 perform set_config('request.jwt.claim.sub',outsider_auth::text,true);
 competitor:=request_business_claim_support(salon2,'I own this business and have ownership evidence to submit.');
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 perform review_business_claim_with_message(competitor,'needs_info','Please provide your authorization document.');
 j:=begin_business_claim(salon2,u,'sms');phone_claim:=(j->>'id')::uuid;stamp:=(j->>'last_sent_at')::timestamptz;
 perform attach_business_claim_challenge(phone_claim,u,stamp,'VE-isolated-communication-qa');
 j:=confirm_business_claim(phone_claim,u,'VE-isolated-communication-qa');
 if j->>'status'<>'waiting' or exists(select 1 from salon_memberships where salon_id=salon2 and status='active') then raise exception 'Phone claim bypassed competing evidence review'; end if;
 -- Team activity is private, permission-scoped, and read receipts belong to each reviewer.
 perform set_config('request.jwt.claim.sub',au::text,true);
 denied:=false;begin perform get_platform_admin_activity();exception when others then denied:=true;end;
 if not denied then raise exception 'Customer read team activity';end if;
 perform set_config('request.jwt.claim.sub',admin_auth::text,true);
 j:=get_platform_admin_activity();
 if jsonb_array_length(j->'items')=0 then raise exception 'Admin activity missing';end if;
 request_key:=(select id from platform_admin_activity_events where report_id=(select report_id from review_support_links where kind='claim' and request_id=competitor) and kind='new_request');
 if request_key is null then raise exception 'New claim team notification missing';end if;
 perform mark_platform_admin_activity_read(array[request_key]);
 if not exists(select 1 from platform_admin_activity_reads where event_id=request_key and user_id=admin_user) then raise exception 'Admin read receipt missing';end if;
 insert into platform_admin_memberships(user_id,role_id,status) select outsider,id,'active' from platform_admin_roles where slug='platform_owner';
 perform set_config('request.jwt.claim.sub',outsider_auth::text,true);
 if exists(select 1 from platform_admin_activity_reads where event_id=request_key and user_id=outsider) then raise exception 'Read receipt shared across team';end if;
 j:=get_platform_admin_activity();
 if not exists(select 1 from jsonb_array_elements(j->'items') e where e->>'id'=request_key::text and (e->>'unread')::boolean) then raise exception 'Second reviewer lost unread notification';end if;
 insert into platform_admin_roles(slug,name,is_system) values('qa-activity-'||outsider,'QA report-only reviewer',false) returning id into limited_role;
 insert into platform_admin_role_permissions(role_id,permission_id) select limited_role,id from platform_admin_permissions where code in ('admin.access','admin.reports.read');
 update platform_admin_memberships set role_id=limited_role where user_id=outsider;
 j:=get_platform_admin_activity();
 if exists(select 1 from jsonb_array_elements(j->'items') e where e->>'id'=request_key::text) then raise exception 'Report-only reviewer saw ownership claim notification';end if;
 perform mark_platform_admin_activity_read(array[request_key]);
 if exists(select 1 from platform_admin_activity_reads where event_id=request_key and user_id=outsider) then raise exception 'Read receipt bypassed claim permission';end if;
 update platform_admin_memberships set status='revoked' where user_id=outsider;
 denied:=false;begin perform get_platform_admin_activity();exception when others then denied:=true;end;
 if not denied then raise exception 'Revoked admin read team feed';end if;
 if has_table_privilege('authenticated','platform_admin_activity_events','select') or has_table_privilege('authenticated','platform_admin_activity_reads','insert') or has_function_privilege('anon','get_platform_admin_activity()','execute') then raise exception 'Team activity privileges exposed';end if;
 raise notice 'Review communication integration assertions passed';
end $$;
rollback;
